//! Differential fixtures generated by the external VMM textutil implementation.
//! 由外置 VMM textutil 实现生成的差异对照样本。

use serde::Deserialize;
use vulcan_memorymesh_core_config::{
    MachineTextCleanerConfig, clean_conversation_text_for_memory, clean_machine_text,
    clip_memory_text_to_default_budget, estimate_memory_tokens, sanitize_postaction_text,
};

/// Loads independently generated external outputs for the implemented cleaning stages.
/// 加载已实现清洗阶段对应的独立生成外置输出。
#[derive(Deserialize)]
struct ExternalTextFixture {
    /// Identifies the synthetic test scenario.
    /// 标识合成测试场景。
    name: String,
    /// Carries the exact synthetic source input.
    /// 携带准确的合成来源输入。
    input: String,
    /// Carries the real Go CleanMemoryText output, not a native-generated expectation.
    /// 携带真实 Go CleanMemoryText 输出，而非原生生成的预期值。
    machine: String,
    /// Carries the real external domestic-profile token estimate.
    /// 携带真实外置国内模型配置的 Token 估算值。
    tokens: u32,
    /// Carries the external default budget output, including its exact truncation marker.
    /// 携带外置默认预算输出，包括其精确截断标记。
    clipped: String,
    /// Carries media and thought cleaning output with preserved line boundaries.
    /// 携带保留行边界的媒体及思考清理输出。
    media: String,
    /// Carries the complete external persistence sanitizer output.
    /// 携带完整外置持久化清洗器输出。
    sanitized: String,
}

/// Compares native Unicode bucket estimates with real external outputs for every fixture.
/// 对每个样本比较原生 Unicode 分桶估算与真实外置输出。
#[test]
fn token_estimation_matches_external_vmm_fixtures() {
    // Load the same independent external oracle used by machine-folding tests.
    // 加载机器折叠测试使用的同一份独立外置基准。
    let fixtures: Vec<ExternalTextFixture> =
        serde_json::from_str(include_str!("fixtures/external_text_cleaner.json"))
            .expect("external fixtures");
    for fixture in fixtures {
        assert_eq!(
            estimate_memory_tokens(&fixture.input),
            fixture.tokens,
            "external tokens: {}",
            fixture.name
        );
    }
}

/// Compares default clipping byte-for-byte, including dense CJK and long Latin inputs.
/// 逐字节比较默认裁剪结果，包括高密度中日韩文本及超长拉丁文本。
#[test]
fn token_clipping_matches_external_vmm_fixtures() {
    // Expectations come from external EnforceTokenBudget, not this Rust implementation.
    // 预期值来自外置 EnforceTokenBudget，而非本 Rust 实现。
    let fixtures: Vec<ExternalTextFixture> =
        serde_json::from_str(include_str!("fixtures/external_text_cleaner.json"))
            .expect("external fixtures");
    for fixture in fixtures {
        assert_eq!(
            clip_memory_text_to_default_budget(&fixture.input),
            fixture.clipped,
            "external budget: {}",
            fixture.name
        );
    }
}

/// Checks media and complete sanitizer output against the independent external oracle.
/// 根据独立外置基准校验媒体清理及完整清洗输出。
#[test]
fn media_and_full_sanitizer_match_external_vmm_fixtures() {
    // Read actual Go outputs without regenerating expectations from the native implementation.
    // 读取实际 Go 输出，不使用原生实现重新生成预期。
    let fixtures: Vec<ExternalTextFixture> =
        serde_json::from_str(include_str!("fixtures/external_text_cleaner.json"))
            .expect("external fixtures");
    for fixture in fixtures {
        assert_eq!(
            clean_conversation_text_for_memory(&fixture.input),
            fixture.media,
            "external media: {}",
            fixture.name
        );
        assert_eq!(
            sanitize_postaction_text(&fixture.input).expect("default sanitizer"),
            fixture.sanitized,
            "external sanitizer: {}",
            fixture.name
        );
    }
}

/// Compares every byte of native machine folding with the recorded external function output.
/// 将原生机器折叠结果与已记录外置函数输出逐字节比较。
#[test]
fn machine_folding_matches_external_vmm_fixtures() {
    // fixtures were generated from external commit 82f05fa5e3c7657e770fefd84e220fba5654ce07.
    // fixtures 从外置提交 82f05fa5e3c7657e770fefd84e220fba5654ce07 生成。
    let fixtures: Vec<ExternalTextFixture> =
        serde_json::from_str(include_str!("fixtures/external_text_cleaner.json"))
            .expect("external fixtures");
    assert_eq!(fixtures.len(), 38);
    for fixture in fixtures {
        assert_eq!(
            clean_machine_text(&fixture.input, &MachineTextCleanerConfig::default())
                .expect("native machine cleaner"),
            fixture.machine,
            "external parity: {}",
            fixture.name
        );
    }
}
